import 'package:flutter/material.dart';
import '../services/app_preferences.dart';
import '../services/model_provider_settings.dart';
import '../services/openai_compatible_provider.dart';
import '../theme/pro_theme.dart';
import '../widgets/pro_app_bar.dart';
import 'mcp_settings_screen.dart';
class ProAdvancedConfig extends StatefulWidget { const ProAdvancedConfig({super.key}); @override State<ProAdvancedConfig> createState()=>_ProAdvancedConfigState(); }
class _ProAdvancedConfigState extends State<ProAdvancedConfig>{
 final _prefs=AppPreferences.instance; ModelProviderMode? _mode; bool _busy=true; final _key=TextEditingController(); final _model=TextEditingController();
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{final mode=await ModelProviderSettings.instance.getMode();final model=await OpenAICompatibleProvider.instance.getModel();if(!mounted)return;setState((){_mode=mode;_model.text=model;_busy=false;});}
 @override void dispose(){_key.dispose();_model.dispose();super.dispose();}
 Future<void> _saveProvider()async{try{if(_mode==ModelProviderMode.openRouter){await OpenAICompatibleProvider.instance.configure(apiKey:_key.text,model:_model.text);}else{await ModelProviderSettings.instance.setMode(ModelProviderMode.local);}if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Configuration saved securely.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:ProTheme.bgDark,appBar:const ProAppBar(title:'Advanced Configuration'),body:Container(decoration:const BoxDecoration(gradient:ProTheme.bgGradient),child:_busy?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[_card('Appearance & language',Column(children:[DropdownButtonFormField<ThemeMode>(value:_prefs.themeMode,dropdownColor:ProTheme.bgCard,decoration:const InputDecoration(labelText:'Theme'),items:ThemeMode.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v){if(v!=null)_prefs.setThemeMode(v);}),const SizedBox(height:12),DropdownButtonFormField<String>(value:_prefs.locale.languageCode,dropdownColor:ProTheme.bgCard,decoration:const InputDecoration(labelText:'Language'),items:const[DropdownMenuItem(value:'ar',child:Text('العربية')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v){if(v!=null)_prefs.setLocale(Locale(v));})])),const SizedBox(height:14),_card('Model runtime',Column(children:[RadioListTile<ModelProviderMode>(value:ModelProviderMode.local,groupValue:_mode,title:const Text('Local GGUF'),onChanged:(v)=>setState(()=>_mode=v)),RadioListTile<ModelProviderMode>(value:ModelProviderMode.openRouter,groupValue:_mode,title:const Text('OpenRouter'),onChanged:(v)=>setState(()=>_mode=v)),if(_mode==ModelProviderMode.openRouter)...[TextField(controller:_key,obscureText:true,decoration:const InputDecoration(labelText:'OpenRouter API key',helperText:'Stored securely; not displayed after saving.')),TextField(controller:_model,decoration:const InputDecoration(labelText:'Model ID'))],Align(alignment:AlignmentDirectional.centerEnd,child:FilledButton(onPressed:_saveProvider,child:const Text('Save provider settings')))])),const SizedBox(height:14),_card('Integrations',ListTile(title:const Text('Manage MCP servers'),subtitle:const Text('Endpoints, secure tokens and tool discovery'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>const McpSettingsScreen())))),const Padding(padding:EdgeInsets.only(top:14),child:Text('Only settings backed by an existing runtime service are exposed. Unsupported crawler rates, expiry rules and social API credentials are omitted.',style:TextStyle(color:ProTheme.textSecondary,fontSize:12,height:1.4)))])));
 Widget _card(String title,Widget child)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:ProTheme.cardGradient,borderRadius:BorderRadius.circular(16),border:Border.all(color:ProTheme.neonGreen.withOpacity(.15))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:ProTheme.neonGreen,fontWeight:FontWeight.bold)),const SizedBox(height:12),child]));
}
